"use strict";(globalThis.webpackChunkidempiere_id_github_io=globalThis.webpackChunkidempiere_id_github_io||[]).push([[80939],{57954(e){e.exports=JSON.parse('{"tag":{"label":"technical","permalink":"/docs/tags/technical","allTagsPath":"/docs/tags","count":80,"items":[{"id":"new-features/v13/account-info-customization","title":"Account Info Customization","description":"Added new feature to allow customization of Account Info window with custom plugin for enhancement or modification of default account info.","permalink":"/docs/new-features/v13/account-info-customization"},{"id":"new-features/v1.0/activesessionlist","title":"Active Login Session List","description":"Active Login Session List: a New Feature in iDempiere 1.0.","permalink":"/docs/new-features/v1.0/activesessionlist"},{"id":"new-features/v10/add-context-variables-in-log-entries","title":"Add Context Variables in log entries","description":"It is now possible to use any Context Variables in the log.","permalink":"/docs/new-features/v10/add-context-variables-in-log-entries"},{"id":"new-features/v2.1/ask-input-within-process","title":"Ask Input Within Process","description":"_String input in Swing_","permalink":"/docs/new-features/v2.1/ask-input-within-process"},{"id":"new-features/v5.1/automatic-external-pack-in","title":"Automatic External Pack In (iDempiere 5.1)","description":"Automatic External Pack In (iDempiere 5.1): a New Feature in iDempiere 5.1.","permalink":"/docs/new-features/v5.1/automatic-external-pack-in"},{"id":"new-features/v1.0/base-language-flexible","title":"Base Language Flexible","description":"Base Language Flexible: a New Feature in iDempiere 1.0.","permalink":"/docs/new-features/v1.0/base-language-flexible"},{"id":"new-features/v1.0/code-best-practices","title":"Code Best Practices","description":"Code Best Practices: a New Feature in iDempiere 1.0.","permalink":"/docs/new-features/v1.0/code-best-practices"},{"id":"new-features/v10/configurable-cache-size-per-table","title":"Configurable Cache Size per Table","description":"Configurable Cache Size per Table: a New Feature in iDempiere 10.","permalink":"/docs/new-features/v10/configurable-cache-size-per-table"},{"id":"new-features/v2.1/configurable-timeout-session","title":"Configurable Timeout Session","description":"Configurable Timeout Session: a New Feature in iDempiere 2.1.","permalink":"/docs/new-features/v2.1/configurable-timeout-session"},{"id":"new-features/v11/constraint-type-for-recordid-and-uu","title":"Constraint Type for RecordID and UU","description":"The purpose of this improvement is to avoid storing IDs of deleted records in the RecordID column.","permalink":"/docs/new-features/v11/constraint-type-for-recordid-and-uu"},{"id":"new-features/v12/context-variable-html-report-theme","title":"Context Variable HTML REPORT THEME","description":"report.css path is configurable using system configuration named HTMLREPORTTHEME.","permalink":"/docs/new-features/v12/context-variable-html-report-theme"},{"id":"new-features/v2.1/create-fields-improvement","title":"Create Fields Improvement","description":"Create Fields Improvement: a New Feature in iDempiere 2.1.","permalink":"/docs/new-features/v2.1/create-fields-improvement"},{"id":"new-features/v8.2/createcomplete-table","title":"Create/Complete Table","description":"Traditionally it has been complicated to create a document table with all the required columns, dependencies, workflow, etc.","permalink":"/docs/new-features/v8.2/createcomplete-table"},{"id":"new-features/v13/custom-key-of-document-sequence","title":"Custom key of document sequence","description":"This change allows to define a custom key for a Document Sequence, using values from the context of the document.","permalink":"/docs/new-features/v13/custom-key-of-document-sequence"},{"id":"new-features/v1.0/customwindowtoolbarbutton","title":"Custom Window Toolbar Buttons","description":"Create custom toolbar button for window using OSGi dynamic service.","permalink":"/docs/new-features/v1.0/customwindowtoolbarbutton"},{"id":"new-features/v2.0/db-objects-in-dictionary","title":"DB Objects in Dictionary","description":"Now you can define and maintain database indexes directly in the dictionary.","permalink":"/docs/new-features/v2.0/db-objects-in-dictionary"},{"id":"new-features/v2.1/debian-installer","title":"Debian Installer","description":"Debian Installer: a New Feature in iDempiere 2.1.","permalink":"/docs/new-features/v2.1/debian-installer"},{"id":"new-features/v10/define-db-views-with-distinct","title":"Define DB views with DISTINCT","description":"A \'Distinct\' checkbox has been added on the View Component tab.","permalink":"/docs/new-features/v10/define-db-views-with-distinct"},{"id":"new-features/v12/define-html-field-at-field-level","title":"Define HTML field at field level","description":"Define HTML field at field level: a New Feature in iDempiere 12.","permalink":"/docs/new-features/v12/define-html-field-at-field-level"},{"id":"new-features/v11/delete-trace-logs","title":"Delete Trace Logs","description":"The purpose of this improvement is to delete old trace logs periodically that generated daily.","permalink":"/docs/new-features/v11/delete-trace-logs"},{"id":"new-features/v13/displaysql-and-display-identifier-in-table-validation","title":"DisplaySQL and Display Identifier in Table Validation","description":"Before this ticket, in search and list type of reference field, it shows identifier columns if Display column is same at _ID column of table.","permalink":"/docs/new-features/v13/displaysql-and-display-identifier-in-table-validation"},{"id":"new-features/v1.0/distributed-cache","title":"Distributed Cache","description":"Distributed Cache: a New Feature in iDempiere 1.0.","permalink":"/docs/new-features/v1.0/distributed-cache"},{"id":"new-features/v11/document-base-type-group","title":"Document Base Type Group","description":"Now you can define new Document Base Type Groups, for example: document types for costing, for accounting, for AR etc.","permalink":"/docs/new-features/v11/document-base-type-group"},{"id":"new-features/v12/document-search-customisable-layout","title":"Document Search Customisable Layout","description":"Document Search Customisable Layout: a New Feature in iDempiere 12.","permalink":"/docs/new-features/v12/document-search-customisable-layout"},{"id":"new-features/v12/email-template-markdown-text","title":"Email Template Markdown Text","description":"Implement markdown text support for email template","permalink":"/docs/new-features/v12/email-template-markdown-text"},{"id":"new-features/v12/export-tree-definition","title":"Export Tree Definition","description":"Before this change, it was only possible to export the main menu tree.","permalink":"/docs/new-features/v12/export-tree-definition"},{"id":"new-features/v13/extensible-report-content-generation","title":"Extensible Report Content Generation","description":"UI-independent OSGi extension points for report rendering and post-processing.","permalink":"/docs/new-features/v13/extensible-report-content-generation"},{"id":"new-features/v13/form-customization","title":"Form Customization","description":"Allow cosmetic customization on forms at tenant level","permalink":"/docs/new-features/v13/form-customization"},{"id":"new-features/v9/form-sql-query","title":"Form SQL Query","description":"The new form SQL Query allows admin users to execute queries in the database.","permalink":"/docs/new-features/v9/form-sql-query"},{"id":"new-features/v11/generate-model-template","title":"Generate Model Template","description":"Generate Model Template: a New Feature in iDempiere 11.","permalink":"/docs/new-features/v11/generate-model-template"},{"id":"new-features/v12/get-image-through-url-from-attachment","title":"Get image through url from attachment","description":"Get image through url from attachment: a New Feature in iDempiere 12.","permalink":"/docs/new-features/v12/get-image-through-url-from-attachment"},{"id":"new-features/v10/hikaricp-connection-pool","title":"HikariCP Connection Pool","description":"The connection pool library has been replaced with HikariCP","permalink":"/docs/new-features/v10/hikaricp-connection-pool"},{"id":"release-changelogs/v10","title":"iDempiere 10 changelog","description":"Bug fixes and non-disruptive features integrated into the iDempiere 10 stable release, listed by date from newest to oldest.","permalink":"/docs/release-changelogs/v10"},{"id":"release-changelogs/v11","title":"iDempiere 11 changelog","description":"Bug fixes and non-disruptive features integrated into the iDempiere 11 stable release, listed by date from newest to oldest.","permalink":"/docs/release-changelogs/v11"},{"id":"release-changelogs/v12","title":"iDempiere 12 changelog","description":"Bug fixes and non-disruptive features integrated into the iDempiere 12 stable release, listed by date from newest to oldest.","permalink":"/docs/release-changelogs/v12"},{"id":"release-changelogs/v13","title":"iDempiere 13 changelog","description":"Bug fixes and non-disruptive features integrated into the iDempiere 13 stable release, listed by date from newest to oldest.","permalink":"/docs/release-changelogs/v13"},{"id":"new-features/v12/imageurl-fieldtype","title":"ImageURL Fieldtype","description":"ImageURL Fieldtype: a New Feature in iDempiere 12.","permalink":"/docs/new-features/v12/imageurl-fieldtype"},{"id":"new-features/v12/implement-escape-sequence-for-text-with-context-variable","title":"Implement escape sequence for text with context variable","description":"Implement escape sequence for text with context variable: a New Feature in iDempiere 12.","permalink":"/docs/new-features/v12/implement-escape-sequence-for-text-with-context-variable"},{"id":"new-features/v9/improve-form-sql-process","title":"Improve Form SQL Process","description":"Improve Form SQL Process: a New Feature in iDempiere 9.","permalink":"/docs/new-features/v9/improve-form-sql-process"},{"id":"new-features/v11/improve-process-log-for-more-advanced-logging-options","title":"Improve Process Log for more advanced logging options","description":"The main goal of this improvement was, to add the option of creating and updating Process Instance Logs (ADPInstanceLog) during the execution of any process.","permalink":"/docs/new-features/v11/improve-process-log-for-more-advanced-logging-options"},{"id":"new-features/v2.1/info-window-process","title":"Info Window Process","description":"Info Window Process: a New Feature in iDempiere 2.1.","permalink":"/docs/new-features/v2.1/info-window-process"},{"id":"new-features/v8.2/inject-context-variables-from-menu","title":"Inject Context Variables From Menu","description":"Inject Context Variables From Menu: a New Feature in iDempiere 8.2.","permalink":"/docs/new-features/v8.2/inject-context-variables-from-menu"},{"id":"new-features/v11/inject-context-variables-from-role","title":"Inject Context Variables From Role","description":"Inject Context Variables From Role: a New Feature in iDempiere 11.","permalink":"/docs/new-features/v11/inject-context-variables-from-role"},{"id":"new-features/v12/iprocessparameterlistener-add-oninit-method","title":"IProcessParameterListener - add onInit method","description":"IProcessParameterListener - add onInit method: a New Feature in iDempiere 12.","permalink":"/docs/new-features/v12/iprocessparameterlistener-add-oninit-method"},{"id":"new-features/v2.0/maintenance-mode","title":"Maintenance Mode","description":"You can define a system configurator key SYSTEM_IN_MAINTENANCE_MODE=Y on the tenant that you want to disable login for maintenance.  If you define SYST","permalink":"/docs/new-features/v2.0/maintenance-mode"},{"id":"new-features/v6.2/manage-plugins-on-webui","title":"Manage Plugins on WebUI","description":"Manage Plugins on WebUI: a New Feature in iDempiere 6.2.","permalink":"/docs/new-features/v6.2/manage-plugins-on-webui"},{"id":"new-features/v2.1/model-cascade-delete","title":"Model Cascade Delete","description":"iDempiere allows to define foreign key constraints on database.","permalink":"/docs/new-features/v2.1/model-cascade-delete"},{"id":"new-features/v2.1/monitor-information-about-sessions","title":"Monitor Information About Sessions","description":"Monitor Information About Sessions: a New Feature in iDempiere 2.1.","permalink":"/docs/new-features/v2.1/monitor-information-about-sessions"},{"id":"new-features/v11/monitor-null-trx","title":"Monitor Null Trx","description":"Monitor Null Trx: a New Feature in iDempiere 11.","permalink":"/docs/new-features/v11/monitor-null-trx"},{"id":"new-features/v4.1/monitor-trx","title":"Monitor Trx","description":"Databases sometimes hit hard to trace conditions, like locks or connection leaks.","permalink":"/docs/new-features/v4.1/monitor-trx"},{"id":"new-features/v12/multiple-sso-provider-support","title":"Multiple SSO Provider Support","description":"This enhancement introduces the ability to configure and support multiple Single Sign-On (SSO) providers in iDempiere.","permalink":"/docs/new-features/v12/multiple-sso-provider-support"},{"id":"new-features/v8.2/operating-system-variables-in-context","title":"Operating System Variables in Context","description":"You can use now operating system environment variables in the context using the prefix $env.","permalink":"/docs/new-features/v8.2/operating-system-variables-in-context"},{"id":"new-features/v8.2/override-virtual-column-definition-in-field","title":"Override Virtual Column Definition in Field","description":"Override Virtual Column Definition in Field: a New Feature in iDempiere 8.2.","permalink":"/docs/new-features/v8.2/override-virtual-column-definition-in-field"},{"id":"new-features/v2.1/parent-composite-keys","title":"Parent Composite Keys","description":"Previously, in order to create a composite key you needed to define all composite columns as parent, but that didn\'t work properly.  Now you can define","permalink":"/docs/new-features/v2.1/parent-composite-keys"},{"id":"new-features/v13/record-attributes-for-decluttering-configuration","title":"Record attributes For Decluttering Configuration","description":"In Application dictionary object like Tab, Table or Column, if we have to add any configuration which are rarely have value, then we keep adding columns on relevent tables.","permalink":"/docs/new-features/v13/record-attributes-for-decluttering-configuration"},{"id":"new-features/v2.0/register-browser-information","title":"Register Browser Information","description":"Now you can find browser/timezone/screen information on the description of the AD_Session table.","permalink":"/docs/new-features/v2.0/register-browser-information"},{"id":"new-features/v6.2/reporting-from-read-only-replica","title":"Reporting from Read-Only Replica","description":"Reporting from Read-Only Replica: a New Feature in iDempiere 6.2.","permalink":"/docs/new-features/v6.2/reporting-from-read-only-replica"},{"id":"new-features/v2.1/restrict-email-to-single-address","title":"Restrict EMail To Single Address","description":"For test systems you can set up the SysConfig key MAIL_DONT_SEND_TO_ADDRESS=Y to avoid sending unwanted messages.","permalink":"/docs/new-features/v2.1/restrict-email-to-single-address"},{"id":"new-features/v2.1/run-reports-in-the-scheduler-using-context-variables-for-dates","title":"Run reports in the scheduler using context variables for dates","description":"This feature gives users the ability to schedule a process/report with variable date parameters.","permalink":"/docs/new-features/v2.1/run-reports-in-the-scheduler-using-context-variables-for-dates"},{"id":"new-features/v8.2/run-script-with-2pack","title":"Run Script with 2Pack (iDempiere 8.2)","description":"Pack In (2Pack) is now able to run scripts when being imported, two types of scripts are supported: Shell Scripts and JSR223 Scripts.","permalink":"/docs/new-features/v8.2/run-script-with-2pack"},{"id":"new-features/v1.0/scheduler-improvements","title":"Scheduler Improvements","description":"This feature enable to define a schedule that can be used in any of the scheduled processes.","permalink":"/docs/new-features/v1.0/scheduler-improvements"},{"id":"new-features/v12/status-line-widget-markdown-and-scoped-style","title":"Status Line Widget Markdown And Scoped Style","description":"Implement markdown and scoped style support for status line widget","permalink":"/docs/new-features/v12/status-line-widget-markdown-and-scoped-style"},{"id":"new-features/v1.0/storage-providers","title":"Storage Providers","description":"Storage Providers: a New Feature in iDempiere 1.0.","permalink":"/docs/new-features/v1.0/storage-providers"},{"id":"new-features/v12/support-for-alternate-db-admin-user","title":"Support for Alternate DB Admin User","description":"Normally there are fixed admin users for Oracle (SYSTEM) and for PostgreSQL (postgres).","permalink":"/docs/new-features/v12/support-for-alternate-db-admin-user"},{"id":"new-features/v11/support-for-pure-uuid-key-tables","title":"Support for pure UUID key tables","description":"Historically iDempiere has always required a primary key _ID (integer java type, numeric(10) database type) on tables to support many features.","permalink":"/docs/new-features/v11/support-for-pure-uuid-key-tables"},{"id":"new-features/v13/support-yaml-and-json-on-packout","title":"support-yaml-and-json-on-packout","description":"Adds YAML and JSON as peer export/import formats for the 2Pack packaging system, alongside the existing XML format.","permalink":"/docs/new-features/v13/support-yaml-and-json-on-packout"},{"id":"new-features/v10/synchronize-print-format-items","title":"Synchronize Print Format Items","description":"Especially in SaaS environnment, it is time consuming to add some columns in Report Views and make them available in reports.","permalink":"/docs/new-features/v10/synchronize-print-format-items"},{"id":"new-features/v6.2/sysconfig-without-cache","title":"SysConfig without Cache","description":"By default all SysConfig values are cached, so when they change it requires a Cache Reset to take the new value.","permalink":"/docs/new-features/v6.2/sysconfig-without-cache"},{"id":"new-features/v11/system-property-to-avoid-cutting-log","title":"System Property to avoid cutting log","description":"Current code is cutting trace log in a hardcoded way.","permalink":"/docs/new-features/v11/system-property-to-avoid-cutting-log"},{"id":"new-features/v11/table-partitioning-support","title":"Table Partitioning Support","description":"Configure the partition information at Table and Column window","permalink":"/docs/new-features/v11/table-partitioning-support"},{"id":"new-features/v12/theme-customization","title":"Theme Customization","description":"Objective of the ticket is to allow minor variations on themes.","permalink":"/docs/new-features/v12/theme-customization"},{"id":"new-features/v2.1/toolbar-and-tab-button","title":"Toolbar and Tab Button","description":"Toolbar and Tab Button: a New Feature in iDempiere 2.1.","permalink":"/docs/new-features/v2.1/toolbar-and-tab-button"},{"id":"new-features/v1.0/translation-improvements","title":"Translation Improvements","description":"Translation Improvements: a New Feature in iDempiere 1.0.","permalink":"/docs/new-features/v1.0/translation-improvements"},{"id":"new-features/v11/tuning-windows-performance","title":"Tuning Windows Performance","description":"iDempiere performance can have problems when trying to open windows with too many records, or windows pointing to complex views.","permalink":"/docs/new-features/v11/tuning-windows-performance"},{"id":"new-features/v12/use-system-configurator-from-css-files","title":"Use System Configurator from css files","description":"Objective of the ticket is to load dynamically some resources such as a background image for the login page.","permalink":"/docs/new-features/v12/use-system-configurator-from-css-files"},{"id":"new-features/v12/validate-required-plugins","title":"Validate Required Plugins","description":"Validate Required Plugins: a New Feature in iDempiere 12.","permalink":"/docs/new-features/v12/validate-required-plugins"},{"id":"new-features/v7.1/virtual-search-column","title":"Virtual Search Column","description":"The goal of the ticket is to allow the configuration of virtual search columns.","permalink":"/docs/new-features/v7.1/virtual-search-column"},{"id":"new-features/v1.0/web-services-improvements","title":"Web Services Improvements","description":"Web Services Improvements: a New Feature in iDempiere 1.0.","permalink":"/docs/new-features/v1.0/web-services-improvements"},{"id":"new-features/v13/weditor-dynamic-display-service","title":"WEditor Dynamic Display OSGI Service","description":"This enhancement exposes the existing WEditor.DynamicDisplayListener interface as an OSGi service","permalink":"/docs/new-features/v13/weditor-dynamic-display-service"},{"id":"new-features/v1.0/windowtabtoolbarbutton","title":"Window Tab Toolbar Buttons","description":"You can now define new process/form toolbar button for a window tab without the need to create a dummy ad_column record.","permalink":"/docs/new-features/v1.0/windowtabtoolbarbutton"}],"unlisted":false}}')}}]);